import { build } from 'esbuild';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
const projectRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const fromRoot = (...parts) => join(projectRoot, ...parts);
const built = await build({ entryPoints: [fromRoot('src', 'interactive-runtime.js')], absWorkingDir: projectRoot, bundle: true, minify: true, format: 'iife', globalName: 'GeoDOMInteractive', write: false, legalComments: 'inline', target: ['es2020'] });
const runtimeJs = built.outputFiles[0].text.replace(/\/\/# sourceMappingURL=.*$/gm, '');
const leafletCss = (await readFile(fromRoot('node_modules', 'leaflet', 'dist', 'leaflet.css'), 'utf8')).replace(/url\(images\/[^)]+\)/g, 'none');
const runtimeCss = leafletCss + '\n' + await readFile(fromRoot('src', 'interactive.css'), 'utf8');
await writeFile(fromRoot('src', 'runtime-assets.js'), '// Generated by npm run build; edit interactive-runtime.js / interactive.css.\nexport const runtimeJs = ' + JSON.stringify(runtimeJs) + ';\nexport const runtimeCss = ' + JSON.stringify(runtimeCss) + ';\n');
await mkdir(fromRoot('dist'), { recursive: true });
await writeFile(fromRoot('dist', 'interactive-runtime.js'), runtimeJs);
await writeFile(fromRoot('dist', 'interactive.css'), runtimeCss);
await writeFile(fromRoot('dist', 'LEAFLET-LICENSE.txt'), await readFile(fromRoot('node_modules', 'leaflet', 'LICENSE'), 'utf8'));
await build({ entryPoints: [fromRoot('src', 'viewer.js')], absWorkingDir: projectRoot, outfile: fromRoot('dist', 'interactive-viewer.js'), bundle: true, minify: true, format: 'esm', legalComments: 'inline', target: ['es2020'] });
console.log('Built portable interactive runtime.');
